<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emberline Protocol — tactical FPS</title>
<style>
  :root{
    --sand:#c9a06a; --rust:#b4552d; --basalt:#232028; --steel:#3a3542;
    --ink:#f2ece1; --muted:#a89c88; --teal:#2dd4bf; --amber:#f0a830; --red:#e5484d;
    --gap:6px;
  }
  *{box-sizing:border-box}
  html,body{margin:0;height:100%;overflow:hidden;background:#17131c;color:var(--ink);
    font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif}
  #game,#game canvas{position:fixed;inset:0;display:block}
  #hud{position:fixed;inset:0;pointer-events:none;z-index:5}
  /* crosshair: 4 lines whose gap grows with spread */
  #cross{position:fixed;left:50%;top:50%;width:0;height:0;--gap:6px}
  #cross i{position:absolute;background:var(--ink);opacity:.92;box-shadow:0 0 2px #000}
  #cross .t{left:-1px;top:calc(-8px - var(--gap));width:2px;height:8px}
  #cross .b{left:-1px;top:var(--gap);width:2px;height:8px}
  #cross .l{top:-1px;left:calc(-8px - var(--gap));height:2px;width:8px}
  #cross .r{top:-1px;left:var(--gap);height:2px;width:8px}
  #dot{position:fixed;left:50%;top:50%;width:2px;height:2px;background:var(--ink);transform:translate(-50%,-50%)}
  #hitm{position:fixed;left:50%;top:50%;width:26px;height:26px;transform:translate(-50%,-50%) rotate(45deg);
    opacity:0;transition:opacity 90ms linear}
  #hitm.on{opacity:1}
  #hitm i{position:absolute;background:#fff}
  #hitm i:nth-child(1){left:12px;top:0;width:2px;height:8px}
  #hitm i:nth-child(2){left:12px;bottom:0;width:2px;height:8px}
  #hitm i:nth-child(3){top:12px;left:0;height:2px;width:8px}
  #hitm i:nth-child(4){top:12px;right:0;height:2px;width:8px}
  #hitm.kill i{background:var(--red)}
  /* bottom-left vitals */
  #vitals{position:fixed;left:28px;bottom:24px;width:250px}
  #hpbar{height:10px;background:#0008;border:1px solid #ffffff2e;border-radius:3px;overflow:hidden}
  #hp-fill{height:100%;width:100px;background:linear-gradient(90deg,var(--teal),#7ef0dd);transition:width 120ms}
  #hp-row{display:flex;align-items:baseline;gap:8px;margin-top:4px;font-variant-numeric:tabular-nums}
  #hp-num{font-size:34px;font-weight:700}
  #armor{font-size:13px;color:var(--muted)}
  /* bottom-right ammo + money */
  #ammo{position:fixed;right:30px;bottom:22px;text-align:right;font-variant-numeric:tabular-nums}
  #ammo-mag{font-size:52px;font-weight:700;letter-spacing:-.02em}
  #ammo-res{font-size:15px;color:var(--muted)}
  #ammo.empty #ammo-mag{color:var(--red)}
  #money{margin-top:2px;font-size:19px;color:var(--amber);font-weight:600}
  /* top-center timer + score */
  #top{position:fixed;top:14px;left:50%;transform:translateX(-50%);text-align:center}
  #timer{font-size:30px;font-weight:700;font-variant-numeric:tabular-nums;text-shadow:0 2px 6px #000}
  #timer.low{color:var(--red)}
  #score{font-size:14px;color:var(--muted);margin-top:2px}
  #score b{color:var(--ink)}
  #objline{font-size:13px;color:var(--teal);margin-top:3px;text-shadow:0 1px 4px #000}
  /* killfeed */
  #feed{position:fixed;top:16px;right:20px;display:grid;gap:4px;justify-items:end;font-size:13px}
  #feed div{background:#000a;padding:4px 10px;border-radius:4px;border-right:3px solid var(--teal)}
  #feed div.bad{border-right-color:var(--red)}
  /* minimap */
  #map{position:fixed;top:16px;left:20px;width:170px;height:132px;background:#100c14d9;
    border:1px solid #ffffff2b;border-radius:4px}
  /* bomb + plant/defuse bars */
  #bombbar{position:fixed;top:96px;left:50%;transform:translateX(-50%);width:280px;display:none;text-align:center}
  #bombbar .lbl{font-size:12px;color:var(--red);font-weight:700;letter-spacing:.08em}
  #bombbar .track{height:8px;background:#000a;border:1px solid var(--red);border-radius:3px;margin-top:3px}
  #bomb-fill{height:100%;width:0;background:var(--red)}
  #chanbar{position:fixed;left:50%;bottom:32%;transform:translateX(-50%);width:260px;display:none;text-align:center}
  #chanbar .lbl{font-size:13px;font-weight:600}
  #chanbar .track{height:8px;background:#000a;border:1px solid var(--teal);border-radius:3px;margin-top:3px}
  #chan-fill{height:100%;width:0;background:var(--teal)}
  #vignette{position:fixed;inset:0;pointer-events:none;opacity:0;transition:opacity 150ms;
    background:radial-gradient(ellipse at center,transparent 55%,#c00000aa 100%)}
  #dmgdir{position:fixed;left:50%;top:50%;width:120px;height:120px;margin:-60px 0 0 -60px;opacity:0}
  /* overlays */
  .overlay{position:fixed;inset:0;display:grid;place-items:center;padding:24px;z-index:10;
    background:rgba(12,9,14,.82)}
  .overlay[hidden]{display:none}
  .panel{width:min(460px,100%);padding:30px 32px;background:#1e1926;border:1px solid #ffffff22;border-radius:8px}
  .panel h1{margin:0 0 6px;font-size:30px;letter-spacing:.01em}
  .panel h1 .em{color:var(--amber)}
  .panel p{margin:0 0 18px;color:var(--muted);font-size:15px;line-height:1.5}
  .panel button{font:inherit;font-weight:600;padding:12px 18px;border-radius:6px;border:1px solid var(--amber);
    background:var(--amber);color:#17131c;cursor:pointer}
  .panel button:hover{background:var(--ink);border-color:var(--ink)}
  .keys{margin:18px 0 0;padding:0;list-style:none;display:grid;gap:7px;font-size:13.5px;color:var(--muted)}
  .keys kbd{border:1px solid #ffffff2e;border-radius:4px;padding:1px 7px;font-family:ui-monospace,monospace;
    color:var(--ink);margin-right:4px}
  /* buy menu */
  #buy .panel{width:min(560px,100%)}
  #buy-items{display:grid;gap:8px;margin:14px 0}
  .buyrow{display:flex;align-items:center;gap:12px;background:#0006;border:1px solid #ffffff1c;border-radius:6px;
    padding:9px 12px;cursor:pointer}
  .buyrow:hover{border-color:var(--amber)}
  .buyrow.owned{opacity:.55}
  .buyrow .k{border:1px solid #ffffff2e;border-radius:4px;padding:1px 8px;font-family:ui-monospace,monospace}
  .buyrow .n{flex:1}.buyrow .n small{display:block;color:var(--muted)}
  .buyrow .p{color:var(--amber);font-weight:700}
  #buy-money{font-size:18px;color:var(--amber);font-weight:700}
  #banner{position:fixed;top:26%;left:0;right:0;text-align:center;z-index:9;pointer-events:none;display:none}
  #banner h2{margin:0;font-size:44px;letter-spacing:.04em;text-shadow:0 3px 14px #000}
  #banner p{margin:6px 0 0;font-size:17px;color:var(--ink);text-shadow:0 2px 8px #000}
  #banner.win h2{color:var(--teal)} #banner.lose h2{color:var(--red)}
</style>
</head>
