  timer: Math.round(store.timer * 10) / 10, money: store.money,
  bomb: store.bomb.state + '@' + store.bomb.site,
  php: Math.round(store.player.hp), palive: store.player.alive,
  ppos: store.player.pos.map((v) => Math.round(v * 10) / 10),
